import json
import time
from datetime import datetime, timezone
from urllib.parse import quote
from urllib.request import Request, urlopen

BASE = "https://api.github.com/search/issues"
HEADERS = {
    "Accept": "application/vnd.github+json",
    "User-Agent": "codex-cli"  # required by GitHub API
}

START = "2024-12-01"
END = "2024-12-31"


def iso_to_dt(s):
    # s like '2024-12-09T02:10:31Z'
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


def fetch_pages(query, per_page=100):
    page = 1
    while True:
        url = f"{BASE}?q={quote(query)}&per_page={per_page}&page={page}"
        req = Request(url, headers=HEADERS)
        with urlopen(req) as resp:
            data = json.load(resp)
            headers = resp.headers
        # Rate limit handling
        remaining = headers.get("X-RateLimit-Remaining")
        reset = headers.get("X-RateLimit-Reset")
        if remaining == "0" and reset:
            sleep_for = max(0, int(reset) - int(time.time()) + 1)
            time.sleep(sleep_for)
        yield data, headers
        link = headers.get("Link", "")
        if 'rel="next"' in link:
            page += 1
        else:
            break


# PRs created in range
pr_query = f"repo:cli/cli is:pr created:{START}..{END}"
pr_total = 0
pr_merged = 0
pr_closed = 0
merge_days_sum = 0.0
contributors = {}

for data, headers in fetch_pages(pr_query):
    for item in data.get("items", []):
        pr_total += 1
        user = (item.get("user") or {}).get("login") or ""
        if user:
            contributors[user] = contributors.get(user, 0) + 1
        created_at = item.get("created_at")
        pr_info = item.get("pull_request") or {}
        merged_at = pr_info.get("merged_at")
        state = item.get("state")
        if merged_at:
            pr_merged += 1
            try:
                delta = iso_to_dt(merged_at) - iso_to_dt(created_at)
                merge_days_sum += delta.total_seconds() / 86400.0
            except Exception:
                pass
        elif state == "closed":
            pr_closed += 1

if pr_merged:
    avg_merge_days = round(merge_days_sum / pr_merged, 1)
else:
    avg_merge_days = 0.0

# Top contributor (most PRs created in range)
if contributors:
    top_contributor = sorted(contributors.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
else:
    top_contributor = ""

# Issues created in range
issue_query = f"repo:cli/cli is:issue created:{START}..{END}"
issue_total = 0
issue_bug = 0

for data, headers in fetch_pages(issue_query):
    for item in data.get("items", []):
        issue_total += 1
        labels = item.get("labels") or []
        if any("bug" in (lbl.get("name", "").lower()) for lbl in labels):
            issue_bug += 1

# Bug issues closed in range
closed_query = f"repo:cli/cli is:issue closed:{START}..{END}"
resolved_bugs = 0

for data, headers in fetch_pages(closed_query):
    for item in data.get("items", []):
        labels = item.get("labels") or []
        if any("bug" in (lbl.get("name", "").lower()) for lbl in labels):
            resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)

print(json.dumps(report, indent=2))
